CREATE OR REPLACE FUNCTION public.get_total_user_count() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(*)::integer FROM auth.users $$; REVOKE EXECUTE ON FUNCTION public.get_total_user_count() FROM PUBLIC; REVOKE EXECUTE ON FUNCTION public.get_total_user_count() FROM anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_total_user_count() TO service_role;